SELECT city, COUNT(*) AS hotels_count
FROM hotels
WHERE city IN ('Алматы', 'Дубай', 'Коканд', 'Стамбул', 'Ташкент', 'Тбилиси', 'Хива')
GROUP BY city
ORDER BY city;
